<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders | ShopNest</title><link rel="stylesheet" href="style.css"></head><body><?php require __DIR__.'/../layout/header.php'; ?><main class="container cart-page"><div class="page-head"><span class="badge">Customer</span><h1>Order History</h1><p>Track your previous and current orders.</p></div><?php if($orders->num_rows===0): ?><div class="empty"><h1>No orders yet</h1><a class="btn btn-primary" href="index.php">Start Shopping</a></div><?php endif; ?><div class="order-list"><?php while($o=$orders->fetch_assoc()): ?><div class="panel order-card"><div class="order-head"><h2>Order #<?= $o['id'] ?></h2><span class="status <?= htmlspecialchars($o['status']) ?>"><?= htmlspecialchars(ucfirst($o['status'])) ?></span></div><p>Date: <?= htmlspecialchars($o['created_at']) ?></p><p>Total: <strong>Tk:<?= number_format($o['total'],2) ?></strong></p><p>Payment: <?= htmlspecialchars($o['method']??'Not available') ?> (<?= htmlspecialchars($o['payment_status']??'pending') ?>)</p><p>Delivery: <?= htmlspecialchars($o['delivery_status']??'pending') ?></p><p>Address: <?= htmlspecialchars($o['customer_address']) ?></p><div class="order-items"><?php $s=$GLOBALS['conn']->prepare("SELECT * FROM order_items WHERE order_id=?");$s->bind_param('i',$o['id']);$s->execute();$its=$s->get_result();while($i=$its->fetch_assoc()): ?><span><?= htmlspecialchars($i['product_name']) ?> × <?= (int)$i['quantity'] ?></span><?php endwhile; ?></div></div><?php endwhile; ?></div></main><?php require __DIR__.'/../layout/footer.php'; ?></body></html>
